def permutations(nums):
    values = sorted(nums)
    n = len(values)
    candidates = []
    current = [None] * n
    def fill(position):
        if position == n:
            candidates.append(list(current))
            return
        for value in values:
            current[position] = value
            fill(position + 1)
    fill(0)
    unique = {tuple(item) for item in candidates if len(set(item)) == n}
    return [list(item) for item in sorted(unique)]
